import java.util.List;

public class FrameStack {

    private List<String> outputFrameStack;

    public FrameStack() {
        this.outputFrameStack = Arrays.asList();
    }

    /**
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        int count = 0;
        if (descriptor.startsWith("(")) {
            // It's a method descriptor
            count = descriptor.substring(1, descriptor.indexOf(')')).split(";").length;
        } else {
            // It's a type descriptor
            count = 1;
        }
        for (int i = 0; i < count; i++) {
            outputFrameStack.remove(outputFrameStack.size() - 1);
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.outputFrameStack = Arrays.asList("int", "double", "String");
        frameStack.pop("(Ljava/lang/String;)V");
        System.out.println(frameStack.outputFrameStack); // Should print: [int, double]
    }
}

