public class CliqueChecker {

    /**
     * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
     * @param graph the graph.
     * @param vertices the vertices to induce the subgraph from.
     * @return true if the induced subgraph is a clique.
     */
    public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        for (V vertex1 : vertices) {
            for (V vertex2 : vertices) {
                if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Example usage
        Set<Integer> vertices = Set.of(1, 2, 3, 4);
        Graph<Integer, DefaultEdge> graph = new org.jgrapht.graph.SimpleGraph<>(DefaultEdge.class);
        graph.addVertex(1);
        graph.addVertex(2);
        graph.addVertex(3);
        graph.addVertex(4);
        graph.addEdge(1, 2);
        graph.addEdge(1, 3);
        graph.addEdge(1, 4);
        graph.addEdge(2, 3);
        graph.addEdge(2, 4);
        graph.addEdge(3, 4);

        boolean isClique = isClique(graph, vertices);
        System.out.println("Is the subgraph a clique? " + isClique);
    }
}

