private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb.hasRemaining()) {
        char c = (char) bb.get(i);
        if (c <= 127) {
            sb.append(c);
        } else if (c > 191 && c < 224) {
            int b1 = bb.get(i + 1) & 0x3F;
            sb.append((char) ((c & 0x1F) << 6 | b1));
            i += 1;
        } else if (c > 223 && c < 240) {
            int b1 = bb.get(i + 1) & 0x3F;
            int b2 = bb.get(i + 2) & 0x3F;
            sb.append((char) ((c & 0x0F) << 12 | b1 << 6 | b2));
