import java.util.Map;

public class StringUnescaper {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        Map<String, String> escapeMap = new HashMap<>();
        escapeMap.put("\\\"", "\"");
        escapeMap.put("\\\\", "\\");
        escapeMap.put("\\'", "'");
        escapeMap.put("\\n", "\n");
        escapeMap.put("\\r", "\r");
        escapeMap.put("\\t", "\t");

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c == '\\' && i + 1 < str.length()) {
                String escapeSequence = "\\" + str.charAt(i + 1);
                if (escapeMap.containsKey(escapeSequence)) {
                    sb.append(escapeMap.get(escapeSequence));
                    i++; // Skip the next character as it's part of an escape sequence
                    continue;
                }
            }
            sb.append(c);
        }

        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            String escapedString = "\\\"Hello\\\" \\n World!";
            String unescapedString = unescapeJava(escapedString);
            System.out.println(unescapedString); // Should print: "Hello" 
                                                 //                    World!
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

