import java.io.DataOutput;

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        out.write(node.data, node.offset, node.length);
        totalSize += node.length;
        node = node.next;
    }
    return totalSize;
}

