public class ByteArray {
    private byte[] bytes;

    public ByteArray(byte[] bytes) {
        this.bytes = bytes;
    }

    public byte[] toByteArray() {
        // Create a new array to hold the bytes
        final int loc0 = this.bytes.length;
        final byte[] loc1 = new byte[loc0];

        // Copy the bytes into the new array
        System.arraycopy(this.bytes, 0, loc1, 0, loc0);

        return loc1;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] originalBytes = {1, 2, 3, 4};
        ByteArray byteArray = new ByteArray(originalBytes);

        byte[] copiedBytes = byteArray.toByteArray();

        // Print the copied bytes
        for (byte b : copiedBytes) {
            System.out.print(b + " ");
        }
    }
}

