import java.io.IOException;

public class ProtocolMessageReader {
    private int pos = 0;
    private int count = 0;
    private byte[] buf;
    private int read;

    public ProtocolMessageReader(byte[] buf, int count) {
        this.buf = buf;
        this.count = count;
    }

    public int readTag() throws IOException {
        if (pos < count) {
            int tag = ((buf[pos] & 0xFF) << 8) | (buf[pos + 1] & 0xFF);
            pos += 2;
            if (tag != 0) {
                return tag;
            } else {
                throw new IOException("Reached EOF unexpectedly");
            }
        } else {
            return 0;
        }
    }
}

